        <div class="mt-6 flex justify-end gap-3"><button type="button" @click="formKind = ''" :disabled="busy">Cancel</button><button class="bg-amber-800" type="submit" :disabled="busy">{{ busy ? 'Saving…' : 'Save and continue' }}</button></div>
      </form></div>
    </main>
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted, onUnmounted } from 'vue'
import { useRoute } from 'vue-router'
import { auth } from '@/config/firebaseConfig'
import { OTP_BACKEND_CANDIDATES } from '@/utils/runtimeConfig'
import OwnerSidebar from '@/components/sidebar/OwnerSidebar.vue'
import SupplierSidebar from '@/components/sidebar/SupplierSidebar.vue'
import Swal from 'sweetalert2'
import { dashboardCharts, reportDefinitions, exportReportCsv } from '@/utils/supplyReporting'

const route = useRoute()
const supplierView = computed(() => route.path.startsWith('/supplier/'))
const department = computed(() => supplierView.value ? 'supplier' : route.meta.supplyDepartment || route.params.department || 'inventory')
const page = computed(() => route.params.page || 'dashboard')
const departmentLabel = computed(() => ({ inventory: 'Inventory Management', procurement: 'Procurement Management', logistics: 'Logistics Management', finance: 'Procurement Finance', management: 'Management Overview', supplier: 'Supplier Portal' })[department.value])
const pageTitle = computed(() => ({ dashboard: 'Dashboard', items: department.value === 'logistics' ? 'Receiving & inspection' : 'Inventory List · DSS', requests: 'Requests', orders: 'Purchase Orders', suppliers: 'Supplier List', reports: 'Reports & Traceability', onboarding: 'Inventory Onboarding', budgets: 'Budget Allocations', invoices: 'Invoices & Payments', rfqs: 'RFQs & Quotations' })[page.value] || 'Supply Management')
const intro = computed(() => ({ inventory: 'Monitor stock, review DSS recommendations, and request replenishment.', procurement: 'Source quotations, record your evaluation, and issue funded purchase orders.', logistics: 'Inspect deliveries and onboard only accepted quantities into inventory.', finance: 'Reserve budgets, match invoices to accepted deliveries, and record supplier payments.', supplier: 'Respond to your RFQs, confirm orders, and track invoice and payment status.' })[department.value])
const tabMap = { management: ['dashboard','reports'], inventory: ['dashboard','items','requests','reports'], procurement: ['dashboard','requests','rfqs','orders','suppliers','reports'], logistics: ['dashboard','items','onboarding','requests','reports'], finance: ['dashboard','budgets','requests','invoices','reports'], supplier: ['dashboard','rfqs','orders','invoices','reports'] }
const clinicSupplyPath = (module, targetPage) => ({ finance: `/finance/procurement/${targetPage}`, management: `/management/supply/${targetPage}` })[module] || `/${module}/${targetPage}`
const tabs = computed(() => (tabMap[department.value] || []).map(key => ({ key, label: ({ items: department.value === 'logistics' ? 'Inspection' : 'Inventory List', rfqs: 'RFQs & Quotes', onboarding: 'Onboarding', invoices: 'Invoices & Payments' })[key] || label(key), to: supplierView.value ? `/supplier/supply/${key}` : clinicSupplyPath(department.value, key) })))
const data = ref({ records: [], items: [], suppliers: [], branches: [], movements: [], permissions: [] }), branchId = ref(''), loading = ref(true), busy = ref(false), error = ref(''), notice = ref('')
const selected = ref(null), history = ref({ history: [], documents: [] }), shareDocument = ref(false)
const search = ref(''), status = ref(''), type = ref(''), departmentFilter = ref(''), supplierFilter = ref(''), categoryFilter = ref(''), fromDate = ref(''), toDate = ref(''), sort = ref('newest'), currentPage = ref(1)
const formKind = ref(''), form = ref({}), formFields = ref([]), formTarget = ref(null), formError = ref('')
const can = permission => data.value.permissions.includes(permission) || data.value.permissions.includes('administrator:full_access')
const api = async (path, body) => {
  await auth.authStateReady?.(); const token = await auth.currentUser?.getIdToken(); if (!token) throw Error('Sign in to continue.')
  let last
  for (const base of OTP_BACKEND_CANDIDATES) {
    let response
    try { response = await fetch(base + '/supply' + path, { method: body === undefined ? 'GET' : 'POST', headers: { Authorization: `Bearer ${token}`, 'content-type': 'application/json' }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) }) } catch (e) { last = e; continue }
    const result = await response.json(); if (!response.ok || !result.success) throw Error(result.error || 'Unable to complete action.'); return result.data
  }
  throw last || Error('Backend is unavailable.')
}
const load = async (silent = false) => {
  if (!silent) loading.value = true
  try { const result = await api('/workspace' + (branchId.value ? '?branchId=' + encodeURIComponent(branchId.value) : '')); data.value = result; branchId.value = result.branchId || ''; error.value = ''; if(result.supplier || branchId.value) api('/reminders',{branchId:branchId.value}).catch(() => {}); if (selected.value) selected.value = [...result.records, ...result.items, ...result.suppliers].find(r => r.id === selected.value.id) || null }
  catch (e) { error.value = e.message } finally { loading.value = false }
}
const label = key => String(key).replace(/([A-Z])/g, ' $1').replace(/^./, c => c.toUpperCase())
const currency = cents => new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP' }).format(Number(cents || 0) / 100)
const timestamp = v => typeof v === 'object' ? (v?._seconds ?? v?.seconds ?? 0) * 1000 : Date.parse(v || '') || 0
const formatDate = v => timestamp(v) ? new Date(timestamp(v)).toLocaleString() : '—'
const supplierName = id => { const s = data.value.suppliers.find(s => s.id === id); return s ? s.businessName || s.name || s.companyName || id : id || '' }
const itemName = id => data.value.items.find(i => i.id === id)?.name || id
const supplierProducts = s => Array.isArray(s.offeredItems) ? s.offeredItems : Array.isArray(s.items) ? s.items : Array.isArray(s.products) ? s.products : Array.isArray(s.supplies) ? s.supplies : []
const kindSets = { management: ['request','procurement','rfq','quotation','evaluation','budget','budgetRequest','financeApproval','budgetAllocation','po','supplierConfirmation','receiving','inspection','discrepancy','invoice','threeWayMatch','payment'], inventory: ['request','receiving','inspection'], procurement: ['procurement','rfq','quotation','evaluation','budgetRequest','financeApproval','po','supplierConfirmation'], logistics: ['po','supplierConfirmation','receiving','inspection','discrepancy'], finance: ['budget','budgetRequest','financeApproval','budgetAllocation','invoice','threeWayMatch','payment','po'], supplier: ['rfq','quotation','po','invoice','payment'] }
const reportKey = ref('')
const availableReports = computed(() => reportDefinitions[department.value] || [])
watch(department, () => { reportKey.value = ''; search.value = '' })
const rows = computed(() => {
  const d = department.value, p = page.value
  if (p === 'items' && d === 'inventory') return data.value.items
  if (p === 'suppliers') return data.value.suppliers
  if (p === 'reports') return (availableReports.value.find(r => r.key === reportKey.value) || availableReports.value[0])?.select(data.value,today()) || []
  const kinds = p === 'rfqs' ? ['rfq','quotation'] : p === 'orders' ? ['po'] : p === 'budgets' ? ['budget'] : p === 'invoices' ? ['invoice','payment'] : p === 'onboarding' ? ['receiving'] : p === 'items' ? ['po','receiving'] : d === 'inventory' ? ['request'] : d === 'logistics' ? ['discrepancy'] : d === 'finance' ? ['budgetRequest'] : ['procurement','budgetRequest','evaluation']
  return data.value.records.filter(r => kinds.includes(r.kind))
})
const statuses = computed(() => [...new Set(rows.value.flatMap(r => r.signals?.length ? r.signals : [r.status || 'In Stock']))].sort())
const types = computed(() => [...new Set(rows.value.map(r => r.kind || r.itemType || 'Supplier'))])
const searchableRows = computed(() => {
  const term=search.value.trim().toLowerCase();if(!term)return rows.value
  const all=[...data.value.records,...data.value.items,...data.value.suppliers,...data.value.movements],direct=all.filter(r=>JSON.stringify(r).toLowerCase().includes(term)),ids=new Set(direct.flatMap(r=>[r.id,...(r.links||[]),r.poId,r.rfqId,r.procurementId,r.invoiceId,r.receivingId,r.supplierId].filter(Boolean)))
  return all.filter(r=>ids.has(r.id)||r.links?.some(id=>ids.has(id))||['poId','rfqId','procurementId','invoiceId','receivingId','supplierId'].some(key=>ids.has(r[key])))
})
const filteredRows = computed(() => searchableRows.value.filter(r => (!status.value || r.status === status.value || r.signals?.includes(status.value)) && (!type.value || (r.kind || r.itemType || 'Supplier') === type.value) && (!departmentFilter.value || String(r.department || '').toLowerCase().includes(departmentFilter.value.toLowerCase())) && (!supplierFilter.value || r.supplierId === supplierFilter.value) && (!categoryFilter.value || String(r.category || '').toLowerCase().includes(categoryFilter.value.toLowerCase())) && (!fromDate.value || timestamp(r.createdAt) >= Date.parse(fromDate.value)) && (!toDate.value || timestamp(r.createdAt) < Date.parse(toDate.value) + 86400000)).sort((a,b) => sort.value === 'name' ? String(a.name || a.number || '').localeCompare(b.name || b.number || '') : (timestamp(b.createdAt) - timestamp(a.createdAt)) * (sort.value === 'oldest' ? -1 : 1)))
