  if(kind==='supplier')f.push(field('name','Company name'),field('contactPerson','Contact person'),field('email','Email','email',false),field('phone','Phone','text',false),field('address','Address','textarea',false),field('category','Category','text',false),field('registrationNumber','Business registration','text',false));
  if(kind==='budget')f.push(field('department','Department'),field('category','Budget category'),field('total','Total budget (PHP)','number'))
  if(kind==='rfq'){const eligibleSuppliers=procurementSupplierOptions(target);form.value={mode:'Online',supplierIds:eligibleSuppliers.filter(s=>target.lines?.some(line=>(line.preferredSupplierId||line.supplierId)===s.value)).map(s=>s.value),deliveryDate:target.requiredDate,deadline:today()};f.push(selectField('mode','Procurement mode',['Manual','Online']),selectField('supplierIds','Invited suppliers',eligibleSuppliers,true),field('deadline','Quotation deadline','date'),field('deliveryDate','Required delivery date','date'),field('deliveryLocation','Delivery location'),field('terms','Terms and specifications','textarea'),field('conditions','Conditions','textarea',false),field('contact','Procurement contact'),field('method','Procurement method'),field('strategy','Supplier strategy','textarea'))}
  if(['quotation','revise','invoice','reviseInvoice'].includes(kind)){
    form.value={lines:target.lines.map(l=>({...l,unitPrice:kind==='quotation'?0:Number(l.unitPrice||0)/100})),tax:Number(target.tax||0)/100,delivery:Number(target.delivery||0)/100,otherCharges:Number(target.otherCharges||0)/100,discount:Number(target.discount||0)/100,validUntil:target.validUntil||today(),leadDays:target.leadDays||0,paymentTerms:target.paymentTerms||'',warranty:target.warranty||'',invoiceNumber:target.invoiceNumber||'',invoiceDate:today(),dueDate:today(),supplierId:data.value.supplierIds?.[0]||''}
    if(kind==='quotation'&&!supplierView.value)f.push(selectField('supplierId','Supplier',supplierOptions().filter(s=>target.supplierIds.includes(s.value))))
    if(kind==='invoice'||kind==='reviseInvoice')f.push(field('invoiceNumber','Supplier invoice number'),field('invoiceDate','Invoice date','date'),field('dueDate','Due date','date'))
    else f.push(field('validUntil','Quotation valid until','date'),field('leadDays','Delivery lead time (days)','number'),field('paymentTerms','Payment terms'),field('warranty','Warranty','text',false),field('notes','Notes / availability','textarea',false))
    f.push(...moneyFields())
  }
  if(kind==='reviseInvoice')f.push(field('remarks','Reason for invoice revision','textarea'));
  if(kind==='select')f.push(field('recommendation','Evaluation recommendation','textarea'),field('justification','Supplier selection justification','textarea'),field('category','Budget category'))
  if(kind==='approve'&&target.kind==='budgetRequest'){form.value.approvedAmount=target.requestedAmount/100;f.push(selectField('budgetId','Department budget',data.value.records.filter(r=>r.kind==='budget').map(b=>({value:b.id,label:`${b.department} · ${b.category} · available ${currency(b.total-b.committed-b.spent)}`}))),field('approvedAmount','Approved amount (PHP)','number'),field('remarks','Finance decision remarks','textarea'))}
  if(['return','reject','resubmit','decline','clarify','resend','cancel','resolve','resource','approvePayment','rejectPayment','resubmitPayment'].includes(kind))f.push(field('remarks','Reason / resolution details','textarea'))
  if(kind==='resolve')f.unshift(selectField('resolutionType','Resolution type',['Return to supplier','Replacement','Credit','Refund','Other resolution']))
  if(kind==='submit'&&target.status==='Returned'){form.value={reason:target.reason,quantity:target.lines[0].quantity};f.push(field('reason','Revised reason','textarea'),field('quantity','Revised quantity','number'))}
  if(kind==='confirm'){form.value.deliveryDate=target.deliveryDate;f.push(field('deliveryDate','Confirmed delivery date','date'),field('remarks','Supplier confirmation details','textarea'))}
  if(kind==='receiving'){form.value={deliveryDate:today(),lines:target.lines.map(l=>({...l,delivered:Math.max(0,l.quantity-Number(target.accepted?.[l.itemId]||0)),accepted:Math.max(0,l.quantity-Number(target.accepted?.[l.itemId]||0)),rejected:0,condition:'Good',reason:'',expiryDate:''}))};f.push(field('reference','Delivery reference'),field('deliveryDate','Delivery date','date'),field('notes','Inspection notes','textarea',false))}
  if(kind==='pay'){form.value={method:'Manual/External',paymentDate:today()};f.push(selectField('method','Payment method',['Manual/External','Electronic']),field('reference','Bank / external payment reference'),field('paymentDate','Payment date','date'),selectField('proofId','Uploaded payment evidence',history.value.documents.map(d=>({value:d.id,label:d.name}))))}
  formFields.value=f
}
const formTitle=computed(()=>formKind.value==='item'?'Inventory item':label(formKind.value)+' '+(formTarget.value?.number||''))
const formTotal=computed(()=>Math.max(0,(form.value.lines||[]).reduce((sum,l)=>sum+Number(l.quantity||0)*Number(l.unitPrice||0),0)+Number(form.value.tax||0)+Number(form.value.delivery||0)+Number(form.value.otherCharges||0)-Number(form.value.discount||0)))
const runAction=async(action,target)=>{
  if(action==='editItem')return openItem(target)
  if(action==='requestItem')return openForm('request',target)
  if(action==='settlePayment'){const invoice=invoiceForPayment(target);if(!invoice){error.value='The linked invoice is unavailable.';return}try{history.value=await api(`/records/${target.id}/history`)}catch(e){error.value=e.message;return}return openForm('pay',invoice)}
  if(['editRequest','editRfq','resource','message','rfq','quotation','revise','reviseInvoice','select','receiving','invoice','pay','return','reject','resubmit','confirm','decline','clarify','resend','cancel','resolve','approvePayment','rejectPayment','resubmitPayment'].includes(action)||(action==='approve'&&target.kind==='budgetRequest')||(action==='submit'&&target.status==='Returned'))return openForm(action,target)
  const answer=await Swal.fire({title:label(action)+' '+target.number+'?',text:'This action updates the linked workflow records.',icon:'question',showCancelButton:true,confirmButtonText:'Confirm'})
  if(!answer.isConfirmed)return
  busy.value=true;try{await api(`/records/${target.id}/actions`,{action});notice.value='Record updated.';await load(true);if(selected.value)await view(selected.value)}catch(e){error.value=e.message}finally{busy.value=false}
}
const saveForm=async()=>{busy.value=true;formError.value='';try{const kind=formKind.value,target=formTarget.value;let path='/records',body={...form.value,kind,branchId:target?.branchId||branchId.value};if(kind==='message'){path='/records/'+target.id+'/messages';body={...form.value}}else if(kind==='supplier'){path='/suppliers'}else if(kind==='item'){path='/items';body={...form.value,branchId:branchId.value,...(target?{id:target.id}:{})}}else if(['rfq','quotation','receiving','invoice'].includes(kind)){body[kind==='rfq'?'procurementId':kind==='quotation'?'rfqId':'poId']=target.id}else if(!['request','budget'].includes(kind)){path=`/records/${target.id}/actions`;body={...form.value,action:kind}}await api(path,body);formKind.value='';notice.value='Saved. Open Details to view related records and the next action.';await load(true);if(selected.value)await view(selected.value)}catch(e){formError.value=e.message}finally{busy.value=false}}
const upload=async event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){error.value='File must be 5 MB or smaller.';return}busy.value=true;try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});await api(`/records/${selected.value.id}/documents`,{name:file.name,contentType:file.type,data:base64,visibility:shareDocument.value?'supplier':'internal'});await view(selected.value)}catch(e){error.value=e.message}finally{busy.value=false;event.target.value=''}}
const download=async document=>{try{const result=await api('/documents/'+document.id);window.open(result.url,'_blank','noopener,noreferrer')}catch(e){error.value=e.message}}
const exportCsv=()=>{const url=URL.createObjectURL(new Blob([exportReportCsv(filteredRows.value)],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=department.value+"-"+page.value+"-"+today()+".csv";a.click();URL.revokeObjectURL(url)}
let timer
onMounted(async()=>{await load();if(department.value==='inventory'&&page.value==='requests'&&route.query.supplierId&&can('inventory:create'))openForm('request');timer=setInterval(()=>{if(!busy.value&&!formKind.value)load(true)},60000)})
onUnmounted(()=>clearInterval(timer))
</script>

