input:not([type=checkbox]),select,textarea{display:block;width:100%;margin-top:.3rem;border:1px solid #475569;border-radius:.5rem;background:#1e293b;color:#f1f5f9;padding:.55rem .7rem}button{border:1px solid #64748b;border-radius:.5rem;padding:.5rem .8rem;font-size:.85rem}button:hover:not(:disabled){background:#334155}button:disabled{opacity:.45;cursor:not-allowed}th,td{padding:.8rem;vertical-align:top}th{font-size:.75rem;color:#cbd5e1}select[multiple]{min-height:7rem}input[type=checkbox]{width:auto}
.module-tabs{display:flex;flex-wrap:wrap;gap:.15rem;border-bottom:1px solid #475569}.module-tab{position:relative;display:inline-flex;align-items:center;padding:.65rem .95rem;color:#94a3b8;font-size:.875rem;font-weight:600;transition:color .15s ease}.module-tab:hover{color:#f8fafc}.module-tab-active{color:#fbbf24}.module-tab-active::after{position:absolute;right:.8rem;bottom:-1px;left:.8rem;height:2px;background:#fbbf24;content:''}.module-actions{display:flex;flex-wrap:wrap;gap:.5rem;align-items:center}.module-action{display:inline-flex;align-items:center;gap:.45rem;border:1px solid #64748b;border-radius:.5rem;padding:.5rem .8rem;color:#e2e8f0;font-size:.85rem;line-height:1.25;transition:background .15s ease,border-color .15s ease}.module-action:hover{border-color:#f59e0b;background:#334155}.module-action span{display:inline-grid;height:1.15rem;width:1.15rem;place-items:center;border-radius:.25rem;background:#334155;color:#fbbf24;font-size:1rem;font-weight:700;line-height:1}
</style>
